const __pageData = JSON.parse('{"title":"MySQL 8.4 行锁工程实践：Record、Gap 与 Next-Key Lock","description":"","frontmatter":{"title":"MySQL 8.4 行锁工程实践：Record、Gap 与 Next-Key Lock","date":"2026-08-17T00:00:00.000Z","category":"MySQL","cover":"/covers/backend.svg","tags":["mysql","innodb","row-lock","gap-lock","next-key-lock"],"excerpt":"从索引记录出发，讲清 InnoDB 的 Record Lock、Gap Lock、Next-Key Lock 与插入意向锁，并用库存预占场景串起隔离级别、加锁范围、阻塞诊断和死锁治理。"},"headers":[],"relativePath":"posts/mysql-innodb-row-locks-engineering.md","filePath":"posts/mysql-innodb-row-locks-engineering.md","lastUpdated":1787128073000}');
